    Implements a basic regex matching algorithm using dynamic programming 
    to handle literal characters, '.', '*', and '+' operators.
    """

    def is_match(i: int, j: int) -> bool:
        if j == len(pattern):
            return i == len(text)

        first_match = i < len(text) and (text[i] == pattern[j] or pattern[j] == '.')

        if j + 1 < len(pattern) and pattern[j + 1] in ('*', '+'):
